fun LazyVGrid(
    columns: Int? = null,
    tracks: List<GridItem>? = null,
    alignment: Alignment? = null,
    spacing: Float? = null,
    content: PathlandScope.() -> Unit = {},
): View {
    val children = collectChildren(content)
    val data = children.singleOrNull() as? ForEachView<*>
    return if (data != null) {
        LazyGridWindowView(
            Components.LAZY_VGRID,
            true,
            data,
            columns ?: 1,
            alignment?.let { Signals.constant(it) },
            null,
            spacing,
            tracks?.let { gridTracks(it) },
        ).registerChild()
    } else {
        coreView(Components.LAZY_VGRID, children) { node, _ ->
            if (alignment != null) node.property(Properties.ALIGNMENT, Signals.constant(alignment))
            if (spacing != null) node.property(Properties.SPACING, Signals.constant(spacing))
            if (tracks != null) node.property(Properties.GRID_TRACKS, Signals.constant(gridTracks(tracks)))
