    alignment: VerticalAlignment? = null,
    pin: Signal<Int?>? = null,
    onVisibleRange: ((Int, Int) -> Unit)? = null,
    content: PathlandScope.() -> Unit = {},
): View = LazyHStack(
    alignment = alignment,
    spacing = spacing.toFloat(),
    pin = pin,
    onVisibleRange = onVisibleRange,
    content = content,
)

fun LazyHStack(
    spacing: Signal<Float>,
    alignment: VerticalAlignment? = null,
    pin: Signal<Int?>? = null,
    onVisibleRange: ((Int, Int) -> Unit)? = null,
    content: PathlandScope.() -> Unit = {},
): View = lazyHStack(
    alignment = alignment?.let { Signals.constant(it) },
    spacingSignal = spacing,
    spacingValue = null,
    pin = pin,
    onVisibleRange = onVisibleRange,
    content = content,
)

fun LazyVGrid(
    columns: Int? = null,
    tracks: List<GridItem>? = null,
    alignment: Alignment? = null,
    spacing: Float? = null,
    content: PathlandScope.() -> Unit = {},
): View {
    val children = collectChildren(content)
    val data = children.singleOrNull() as? ForEachView<*>
    return if (data != null) {
        LazyGridWindowView(
            Components.LAZY_VGRID,
            true,
            data,
            columns ?: 1,
            alignment?.let { Signals.constant(it) },
            null,
            spacing,
            tracks?.let { gridTracks(it) },
        ).registerChild()
    } else {
        coreView(Components.LAZY_VGRID, children) { node, _ ->
            if (alignment != null) node.property(Properties.ALIGNMENT, Signals.constant(alignment))
            if (spacing != null) node.property(Properties.SPACING, Signals.constant(spacing))
            if (tracks != null) node.property(Properties.GRID_TRACKS, Signals.constant(gridTracks(tracks)))
            if (columns != null) node.property(Properties.GRID_COLUMNS, Signals.constant(columns))
        }.registerChild()
    }
}

fun LazyHGrid(
    rows: Int? = null,
    tracks: List<GridItem>? = null,
    alignment: Alignment? = null,
    spacing: Float? = null,
    content: PathlandScope.() -> Unit = {},
): View {
    val children = collectChildren(content)
    val data = children.singleOrNull() as? ForEachView<*>
    return if (data != null) {
        LazyGridWindowView(
            Components.LAZY_HGRID,
            false,
            data,
            rows ?: 1,
            alignment?.let { Signals.constant(it) },
            null,
            spacing,
            tracks?.let { gridTracks(it) },
        ).registerChild()
    } else {
        coreView(Components.LAZY_HGRID, children) { node, _ ->
            if (alignment != null) node.property(Properties.ALIGNMENT, Signals.constant(alignment))
            if (spacing != null) node.property(Properties.SPACING, Signals.constant(spacing))
            if (tracks != null) node.property(Properties.GRID_TRACKS, Signals.constant(gridTracks(tracks)))
            if (rows != null) node.property(Properties.GRID_ROWS, Signals.constant(rows))
        }.registerChild()
    }
}

internal fun gridTracks(tracks: List<GridItem>): String = tracks.joinToString(",") { it.token }

