package dev.pathland.demo.music.library

import dev.pathland.core.protocol.Categories
import dev.pathland.core.protocol.Commands
import dev.pathland.core.protocol.Components
import dev.pathland.core.protocol.Properties
import dev.pathland.core.transport.FrameOpcodeSink
import dev.pathland.core.transport.ProtocolFrame
import dev.pathland.demo.music.MusicPlayerView
import dev.pathland.demo.music.service.MediaPlayerService
import dev.pathland.view.core.Environment
import dev.pathland.view.core.Roles
import dev.pathland.view.dsl.VStack
import dev.pathland.view.dsl.environment
import dev.pathland.view.engine.Emitter
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class TrackRowViewTest {

    @Test
    fun selectedBackgroundAndPlayingIconAreIndependent() {
        val service = MediaPlayerService()
        service.trackIndex.set(0)
        service.focusedIndex.set(1)

        val sink = FrameOpcodeSink()
        Emitter(sink).mount(
            VStack {
                TrackRowView(service.tracks[0], 0)
                TrackRowView(service.tracks[1], 1)
            }.environment(MediaPlayerService.KEY, service),
            Environment.DEFAULT,
        )

        var frame = sink.frame()
        var rows = rowIds(frame)
        assertEquals(2, rows.size)
        assertEquals(0, backgroundColor(frame, rows[0]), "playing row is not selected")
        assertEquals(MusicPlayerView.ACTIVE_ROW_BG.argb, backgroundColor(frame, rows[1]))
        assertEquals(rows[0], playingIconParent(frame), "the current track has the playing icon")
        assertTrue(hasIcon(frame, "volume"))

        service.focusedIndex.set(0)
        frame = sink.frame()
        assertEquals(MusicPlayerView.ACTIVE_ROW_BG.argb, backgroundColor(frame, rows[0]))
        assertEquals(0, backgroundColor(frame, rows[1]), "selection moves independently of playback")

        service.trackIndex.set(1)
        frame = sink.frame()
        assertEquals(rows[1], playingIconParent(frame), "the playing icon follows the current track")
        assertEquals(1, countIcons(frame))
    }

    private fun rowIds(frame: ProtocolFrame): List<Int> =
        frame.opcodes().filter {
            it.category() == Categories.PARAMETER &&
                it.command() == Commands.Parameter.SET_PROPERTY &&
                (it.b() and 0xffff) == Properties.ROLE &&
                it.c() == Roles.LIST_ITEM
        }.map { it.a() }.distinct()

    private fun backgroundColor(frame: ProtocolFrame, rowId: Int): Int? =
        frame.opcodes().firstOrNull {
            it.category() == Categories.PARAMETER &&
                it.command() == Commands.Parameter.SET_PROPERTY &&
                it.a() == rowId &&
                (it.b() and 0xffff) == Properties.BACKGROUND_COLOR
        }?.c()

    private fun countIcons(frame: ProtocolFrame): Int =
        frame.opcodes().count {
            it.category() == Categories.TREE &&
                it.command() == Commands.Tree.CREATE_NODE &&
                it.b() == Components.ICON
        }

    private fun playingIconParent(frame: ProtocolFrame): Int? {
        val iconId = frame.opcodes().firstOrNull {
            it.category() == Categories.TREE &&
                it.command() == Commands.Tree.CREATE_NODE &&
                it.b() == Components.ICON
        }?.a() ?: return null
        return frame.opcodes().firstOrNull {
            it.category() == Categories.TREE &&
                it.command() == Commands.Tree.INSERT_CHILD &&
                it.b() == iconId
        }?.a()
    }

    private fun hasIcon(frame: ProtocolFrame, name: String): Boolean =
        frame.opcodes().any {
            it.category() == Categories.PARAMETER &&
                it.command() == Commands.Parameter.SET_PROPERTY &&
                (it.b() and 0xffff) == Properties.ICON_NAME &&
                frame.stringAt(it.c()) == name
        }
}
