  }
  send(data: Uint8Array): void {
    this.sent.push(data);
  }
  close(): void {
    this.readyState = 3;
  }
  emitOpen(): void {
    this.readyState = 1;
    this.onopen?.();
  }
  emitMessage(data: unknown): void {
    this.onmessage?.({ data });
